const ChakraSpinner = () => {
    const getElementPosition = (index, total) => {
        // Angle range for semicircle (180 degrees in radians)
        const angleRange = Math.PI
        // Start angle (to center the semicircle)
        const startAngle = 0
        // Calculate angle for this element
        const angle = startAngle + (angleRange * index) / (total - 1)

        // Radius of the semicircle (adjust based on container size)
        const radius = (window.innerWidth + 100) / 4
        console.log(radius, 'this is the radius');

        // Calculate x and y positions
        const x = 50 + (radius * Math.cos(angle)) / 8 // Convert to percentage and scale
        const y = 60 - (radius * Math.sin(angle)) / 10 // Convert to percentage and scale

        return { x: `${x}%`, y: `${y}%` }
    }

    return (
        <div
            className={styles.spinnerContainer}>
            <div className={styles.spinPath}>
                {[...chakraList, ...chakraList].map((item, i) => (
                    <div key={i}
                        className={styles.itemContent}
                        style={{
                            animationDelay: `${((i * 5) / chakraList.length * 2).toFixed(
                                1
                            )}s`,
                        }}>
                        <ChakraCard icon={item.icon}
                            label={item.label}
                            color={item.color} />
                    </div>
                ))}
            </div>
            {/* <div className={styles.spinPath}> */}
            {/* <div className="">
                {chakraList.map((item, index) => {
                    const position = getElementPosition(index, chakraList.length)

                    return (
                        <div
                            key={index}
                            className="absolute transform -translate-x-1/2 -translate-y-1/2"
                            style={{
                                left: position.x,
                                top: position.y,
                            }}
                        >
                            <ChakraCard icon={item.icon}
                                label={item.label}
                                color={item.color} />
                        </div>
                    )
                })}
            </div> */}
            {/* </div> */}
        </div>
    )
}

export default ChakraSpinner;

const ChakraCard = ({ icon, label, color }) => {
    return (
        <div className="w-[96px] h-[96px] flex flex-col gap-[10px] items-center justify-center">
            {icon}

            <div className="w-[100px] h-[20px] flex items-center justify-center px-[10px]"
                style={{
                    background: color,
                    clipPath: "path('M93.8706 7.67975C92.9206 5.92975 91.6306 0.509766 84.8006 0.509766H13.0906C6.25061 0.509766 4.96063 5.92975 4.02063 7.67975C3.08063 9.42975 0.890625 11.2397 0.890625 11.2397C0.890625 11.2397 3.07063 13.0397 4.02063 14.7997C4.96063 16.5497 6.25061 21.9698 13.0906 21.9698H84.8006C91.6406 21.9698 92.9206 16.5497 93.8706 14.7997C94.8106 13.0497 97.0006 11.2397 97.0006 11.2397C97.0006 11.2397 94.8206 9.42975 93.8706 7.67975Z')"
                }}>
                <span className="text-white text-[12px] leading-[1.6] font-semibold">
                    {label}
                </span>
            </div>
        </div>
    )
}
